def clean(value, number):
    value = value or ""
    for old, new in REPLACE.items():
        value = value.replace(old, new)
    value = value.replace("wg.", "พฐ.").replace("Wg.", "พฐ.").replace("ng.", "พฐ.").replace("uu.", "ปป.").replace("Uv.", "ปป.")
    value = re.split(rf"\s+{number + 1}[.,)]\s+(?=[ก-๙])", value, maxsplit=1)[0] if number < 100 else value
    value = re.sub(r"^[^ก-๙0-9“\"]+(?=[ก-๙0-9“\"])", "", value)
    value = re.sub(r"\s+[A-Za-z][A-Za-z0-9$%&*+=<>\[\]{}_-]*(?:\s+[A-Za-z0-9$%&*+=<>\[\]{}_-]+)*\s*$", "", value)
    value = re.sub(r"\s+", " ", value).strip(" ·|_-–—,:;")
    return value


